import json
from pathlib import Path
p=Path('content/grammar.json'); d=json.loads(p.read_text(encoding='utf8'))
def patch(pattern,meaning,formation,examples,prompt,options,answer):
    x=next(i for l in d['lessons'] for i in l['items'] if i['pattern']==pattern)
    x.update({'meaning':meaning,'formation':formation,'usage':'Use the construction for the relationship shown in these examples.','register':'neutral','nuance':'The exact interpretation follows the clause and context.','examples':[{'jp':a,'reading':b,'romaji':c,'en':e} for a,b,c,e in examples],'mistake':'Check the required attachment before conjugating the final verb.','comparison':'Compare the time, agency, and polarity with nearby patterns.','question':{'prompt':prompt,'options':options,'answer':answer,'explanation':'The surrounding context requires this pattern.'}})
patch('つつある','be gradually; be in the process of','V masu-stem + つつある',[( '地方の人口は減りつつある。','ちほうのじんこうはへりつつある。','Chihō no jinkō wa heri tsutsu aru.','The rural population is gradually decreasing.'),('環境への関心が高まりつつある。','かんきょうへのかんしんがたかまりつつある。','Kankyō e no kanshin ga takamari tsutsu aru.','Interest in the environment is beginning to grow.'),('新制度は定着しつつある。','しんせいどはていちゃくしつつある。','Shin seido wa teichaku shi tsutsu aru.','The new system is gradually taking root.')],'社会は大きく変わり（　）。',['つつある','ことにする','たびに','ばかりで'],'つつある')
patch('ために','for the purpose of; in order to','V dictionary + ために; N の + ために',[('日本で働くために、日本語を勉強している。','にほんではたらくために、にほんごをべんきょうしている。','Nihon de hataraku tame ni, nihongo o benkyō shite iru.','I study Japanese in order to work in Japan.'),('家族のために、毎月お金を送っている。','かぞくのために、まいげつおかねをおくっている。','Kazoku no tame ni, maigetsu okane o okutte iru.','I send money every month for my family.'),('試験に合格するために、毎朝復習する。','しけんにごうかくするために、まいあさふくしゅうする。','Shiken ni gōkaku suru tame ni, maiasa fukushū suru.','I review every morning to pass the exam.')],'留学する（　）、貯金を始めた。',['ために','つつある','ばかりだ','ごとに'],'ために')
patch('ように','so that; in order that','V dictionary/ない + ように',[('忘れないように、メモを取った。','わすれないように、めもをとった。','Wasurenai yō ni, memo o totta.','I took notes so that I would not forget.'),('誰でも読めるように、大きな字で書いてください。','だれでもよめるように、おおきなじでかいてください。','Dare demo yomeru yō ni, ōkina ji de kaite kudasai.','Write in large letters so anyone can read it.'),('風邪をひかないように、暖かくしてください。','かぜをひかないように、あたたかくしてください。','Kaze o hikanai yō ni, atatakaku shite kudasai.','Keep warm so that you do not catch a cold.')],'みんなに聞こえる（　）、大きな声で話した。',['ように','ために','ついでに','以来'],'ように')
patch('に沿って','along; in accordance with','N + に沿って',[('計画に沿って作業を進めます。','けいかくにそってさぎょうをすすめます。','Keikaku ni sotte sagyō o susumemasu.','We will proceed according to the plan.'),('川に沿って道を歩いた。','かわにそってみちをあるいた。','Kawa ni sotte michi o aruita.','I walked along the road beside the river.'),('会社の方針に沿って研修を改めた。','かいしゃのほうしんにそってけんしゅうをあらためた。','Kaisha no hōshin ni sotte kenshū o aratameta.','We revised the training in line with company policy.')],'案内図（　）進んでください。',['に沿って','に役立って','ために','ばかり'],'に沿って')
patch('に向けて','toward; aimed at','N + に向けて',[('駅に向けて走り出した。','えきにむけてはしりだした。','Eki ni mukete hashiridashita.','I started running toward the station.'),('試合に向けて毎日練習している。','しあいにむけてまいにちれんしゅうしている。','Shiai ni mukete mainichi renshū shite iru.','I practice every day for the match.'),('若者に向けて新しい講座を開く。','わかものにむけてあたらしいこうざをひらく。','Wakamono ni mukete atarashii kōza o hiraku.','We will open a course aimed at young people.')],'卒業（　）準備を進めている。',['に向けて','に沿って','以来','たびに'],'に向けて')
patch('に役立つ','be useful for; help with','N + に役立つ',[('この辞書は作文の練習に役立つ。','このじしょはさくぶんのれんしゅうにやくだつ。','Kono jisho wa sakubun no renshū ni yakudatsu.','This dictionary is useful for composition practice.'),('早寝は健康に役立ちます。','はやねはけんこうにやくだちます。','Hayane wa kenkō ni yakudachimasu.','Going to bed early helps one’s health.'),('経験が就職に役立った。','けいけんがしゅうしょくにやくだった。','Keiken ga shūshoku ni yakudatta.','The experience helped with finding a job.')],'このアプリは漢字の暗記（　）。',['に役立つ','に向けて','つつある','たびに'],'に役立つ')
patch('ておく','do in advance','Vて + おく',[('会議の前に資料を印刷しておく。','かいぎのまえにしりょうをいんさつしておく。','Kaigi no mae ni shiryō o insatsu shite oku.','I will print the handouts before the meeting.'),('帰る前に窓を閉めておいてください。','かえるまえにまどをしめておいてください。','Kaeru mae ni mado o shimete oite kudasai.','Please close the windows before leaving.'),('明日使うのでここに置いておこう。','あしたつかうのでここにおいておこう。','Ashita tsukau node koko ni oite okō.','I will leave it here because I will use it tomorrow.')],'忘れないように予約して（　）。',['おく','ある','しまう','みる'],'おく')
patch('てある','has been done and remains','Vて + ある',[('机の上に資料が並べてある。','つくえのうえにしりょうがならべてある。','Tsukue no ue ni shiryō ga narabete aru.','The materials have been laid out on the desk.'),('入口に案内が貼ってあります。','いりぐちにあんないがはってあります。','Iriguchi ni annai ga hatte arimasu.','Instructions have been posted at the entrance.'),('道具は箱に入れてある。','どうぐははこにいれてある。','Dōgu wa hako ni irete aru.','The tools have been put in the box.')],'会議のため椅子が並べて（　）。',['ある','おく','しまう','みる'],'ある')
patch('てしまう','finish; unfortunately end up','Vて + しまう',[('宿題を全部やってしまった。','しゅくだいをぜんぶやってしまった。','Shukudai o zenbu yatte shimatta.','I finished all my homework.'),('大切なメールを消してしまった。','たいせつなめーるをけしてしまった。','Taisetsu na mēru o keshite shimatta.','I accidentally deleted an important email.'),('電車で寝てしまい乗り過ごした。','でんしゃでねてしまいのりすごした。','Densha de nete shimai norisugoshita.','I fell asleep and missed my stop.')],'うっかり財布を忘れて（　）。',['しまった','おいた','あった','みた'],'しまった')
patch('ばかりだ','only keeps; continues to','V dictionary + ばかりだ',[('人口は減るばかりだ。','じんこうはへるばかりだ。','Jinkō wa heru bakari da.','The population only keeps decreasing.'),('仕事が増えるばかりで困っている。','しごとがふえるばかりでこまっている。','Shigoto ga fueru bakari de komatte iru.','Work keeps increasing, which is a problem.'),('痛みは強くなるばかりだった。','いたみはつよくなるばかりだった。','Itami wa tsuyoku naru bakari datta.','The pain only grew stronger.')],'空き家が増える（　）だ。',['ばかり','たばかり','ついで','ごと'],'ばかり')
patch('ところだ','be about to; be doing; have just','V dictionary/ている/た + ところだ',[('今から昼食を食べるところです。','いまからちゅうしょくをたべるところです。','Ima kara chūshoku o taberu tokoro desu.','I am just about to eat lunch.'),('今電話で話しているところだ。','いまでんわではなしているところだ。','Ima denwa de hanashite iru tokoro da.','I am in the middle of a phone call.'),('たった今駅に着いたところです。','たったいまえきについたところです。','Tatta ima eki ni tsuita tokoro desu.','I have just arrived at the station.')],'今から出発する（　）です。',['ところ','ばかり','つもり','ごと'],'ところ')
patch('までに','by; no later than','N + までに',[('金曜日までにレポートを提出してください。','きんようびまでにれぽーとをていしゅつしてください。','Kin-yōbi made ni repōto o teishutsu shite kudasai.','Please submit the report by Friday.'),('寝るまでにメールを確認する。','ねるまでにめーるをかくにんする。','Neru made ni mēru o kakunin suru.','I will check email before bed.'),('三十分までに全員集まった。','さんじゅっぷんまでにぜんいんあつまった。','Sanjuppun made ni zen-in atsumatta.','Everyone gathered within thirty minutes.')],'申込書は月末（　）出してください。',['までに','まで','うちに','以来'],'までに')
patch('うちに','while; before a state changes','V dictionary/ない, い-adj, Nの + うちに',[('明るいうちに帰りましょう。','あかるいうちにかえりましょう。','Akarui uchi ni kaerimashō.','Let’s go home while it is still light.'),('忘れないうちにメモしてください。','わすれないうちにめもしてください。','Wasurenai uchi ni memo shite kudasai.','Please take notes before you forget.'),('元気なうちに旅行したい。','げんきなうちにりょこうしたい。','Genki na uchi ni ryokō shitai.','I want to travel while I am healthy.')],'忘れない（　）メモを取った。',['うちに','までに','以来','たびに'],'うちに')
patch('間に','while; during a period','N の/ Vている + 間に',[('留守の間に荷物が届いた。','るすのあいだににもつがとどいた。','Rusu no aida ni nimotsu ga todoita.','A package arrived while I was away.'),('母が料理している間に皿を並べた。','ははがりょうりしているあいだにさらをならべた。','Haha ga ryōri shite iru aida ni sara o narabeta.','I set plates while my mother cooked.'),('夏休みの間に本を五冊読んだ。','なつやすみのあいだにほんをごさつよんだ。','Natsu yasumi no aida ni hon o gosatsu yonda.','I read five books during summer vacation.')],'母が料理している（　）皿を並べた。',['間に','までに','以来','ばかり'],'間に')
patch('以来','ever since','N + 以来; Vて + 以来',[('卒業以来、先生に会っていない。','そつぎょういらい、せんせいにあっていない。','Sotsugyō irai sensei ni atte inai.','I have not seen my teacher since graduation.'),('引っ越して以来、電車を使わなくなった。','ひっこしていらい、でんしゃをつかわなくなった。','Hikkoshite irai densha o tsukawanaku natta.','Since moving, I stopped using trains.'),('事故以来、運転には慎重になった。','じこいらい、うんてんにはしんちょうになった。','Jiko irai unten ni wa shinchō ni natta.','Since the accident, I have become cautious about driving.')],'卒業（　）連絡していない。',['以来','までに','うちに','ごとに'],'以来')
p.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf8')
print('patched 15 entries')
